{
  "$schema": "https://html-doc.dev/schema/page-v1.json",
  "kind": "page",
  "schema_version": 1,
  "title": "My note",
  "accent": "teal",
  "meta": {
    "eyebrow": "Notes",
    "subtitle": "One-line subtitle below the H1.",
    "date": "2026-05-18",
    "order": 10,
    "summary": "One-line summary for nav tooltips and llms.txt."
  },
  "blocks": [
    { "kind": "tldr", "summary": "...", "bullets": ["..."] },
    { "kind": "section", "id": "overview", "title": "Overview", "blocks": [
      { "kind": "paragraph", "content": "Plain prose works as a string." }
    ]}
  ]
}

// Plain string
{ "kind": "paragraph", "content": "Just prose, nothing fancy." }

// Array — mix strings and inline nodes
{ "kind": "paragraph", "content": [
  "The Iceberg format gives ",
  { "kind": "glossary-term", "term": "ACID", "text": "ACID" },
  " transactions, see also ",
  { "kind": "ext-ref", "name": "Apache Iceberg", "text": "the project home" },
  " — runs on ",
  { "kind": "code", "text": "S3" },
  ", HDFS, or any object store."
] }
